# -*- coding: utf-8 -*-

SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">MEKKE DÖNEMİ AĞIR İMTİHAN YILLARI: BOYKOT, HÜZÜN YILI VE TAİF</text>\n  <rect x="20" y="45" width="215" height="195" rx="10" fill="#fffbeb" stroke="#d97706" stroke-width="2"/>\n  <text x="127" y="66" text-anchor="middle" font-size="12" font-weight="bold" fill="#b45309">1. BOYKOT YILLARI (616-619)</text>\n  <text x="32" y="90" font-size="10.5" fill="#78350f">• Yer: Şi\'b-i Ebû Tâlib Mahallesi</text>\n  <text x="32" y="110" font-size="10.5" fill="#78350f">• Kapsam: Haşimoğulları ve</text>\n  <text x="40" y="125" font-size="10.5" fill="#78350f">Muttaliboğulları kuşatıldı.</text>\n  <text x="32" y="145" font-size="10.5" fill="#78350f">• Yasaklar: Evlilik, alışveriş,</text>\n  <text x="40" y="160" font-size="10.5" fill="#78350f">konuşma ve barış yasağı.</text>\n  <text x="32" y="182" font-size="10.5" font-weight="bold" fill="#92400e">• Sonuç: Hişâm b. Amr ve</text>\n  <text x="40" y="197" font-size="10.5" fill="#92400e">arkadaşlarının girişimiyle</text>\n  <text x="40" y="212" font-size="10.5" fill="#92400e">3 yıl sonra sona erdi (619).</text>\n  <rect x="243" y="45" width="214" height="195" rx="10" fill="#fff1f2" stroke="#e11d48" stroke-width="2"/>\n  <text x="350" y="66" text-anchor="middle" font-size="12" font-weight="bold" fill="#9f1239">2. HÜZÜN YILI (619)</text>\n  <text x="255" y="90" font-size="10.5" fill="#881337">• Dönem: Nübüvvetin 10. yılı</text>\n  <text x="255" y="110" font-size="10.5" font-weight="bold" fill="#9f1239">• İki Büyük Kayıp:</text>\n  <text x="263" y="128" font-size="10.5" fill="#881337">1) Amcası Ebû Tâlib\'in vefatı</text>\n  <text x="270" y="143" font-size="10" fill="#9f1239">(Mekke\'de dış himaye bitti)</text>\n  <text x="263" y="163" font-size="10.5" fill="#881337">2) Eşi Hz. Hatice\'nin vefatı</text>\n  <text x="270" y="178" font-size="10" fill="#9f1239">(En büyük manevi dayanak)</text>\n  <text x="255" y="200" font-size="10.5" fill="#881337">• Ebû Leheb kabile reisi olunca</text>\n  <text x="263" y="215" font-size="10.5" fill="#881337">Mekke\'de baskılar zirveye çıktı.</text>\n  <rect x="465" y="45" width="215" height="195" rx="10" fill="#f0fdf4" stroke="#16a34a" stroke-width="2"/>\n  <text x="572" y="66" text-anchor="middle" font-size="12" font-weight="bold" fill="#15803d">3. TAİF YOLCULUĞU (620)</text>\n  <text x="477" y="90" font-size="10.5" fill="#14532d">• Yol Arkadaşı: Zeyd b. Hârise</text>\n  <text x="477" y="110" font-size="10.5" fill="#14532d">• Muhatap: Sakîf Kabilesi</text>\n  <text x="477" y="130" font-size="10.5" fill="#14532d">• Tepki: Taşlı saldırı; Peygamber</text>\n  <text x="485" y="145" font-size="10.5" fill="#14532d">beddua yerine hidayet diledi.</text>\n  <text x="477" y="167" font-size="10.5" font-weight="bold" fill="#166534">• Üzüm Bağı: Ninovalı köle</text>\n  <text x="485" y="182" font-size="10.5" fill="#166534">Addâs Müslüman oldu.</text>\n  <text x="477" y="202" font-size="10.5" fill="#14532d">• Dönüş: Mut\'im b. Adî emanı</text>\n  <text x="485" y="217" font-size="10.5" fill="#14532d">(himayesi) ile Mekke\'ye giriş.</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">İSRÂ VE MİRAÇ MUCİZESİ İLE AKABE BİATLARI (620 - 622)</text>\n  <rect x="20" y="45" width="320" height="195" rx="10" fill="#eff6ff" stroke="#2563eb" stroke-width="2"/>\n  <text x="180" y="66" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#1d4ed8">İSRÂ VE MİRAÇ (İLAHİ TESELLİ)</text>\n  <text x="35" y="92" font-size="11" font-weight="bold" fill="#1e3a8a">• İsrâ (Gece Yürüyüşü — İsrâ Suresi 1):</text>\n  <text x="45" y="108" font-size="10.5" fill="#1e40af">Mescid-i Harâm\'dan (Mekke) Mescid-i Aksâ\'ya (Kudüs).</text>\n  <text x="35" y="130" font-size="11" font-weight="bold" fill="#1e3a8a">• Miraç (Göklere Yükseliş):</text>\n  <text x="45" y="146" font-size="10.5" fill="#1e40af">Mescid-i Aksâ\'dan ilahi huzura yükseltiliş.</text>\n  <text x="35" y="168" font-size="11" font-weight="bold" fill="#15803d">• Miraç Gecesi Verilen 3 İlahi Hediye:</text>\n  <text x="45" y="185" font-size="10.5" fill="#166534">1) Beş vakit namazın farz kılınması</text>\n  <text x="45" y="201" font-size="10.5" fill="#166534">2) Bakara suresi son 2 ayeti (Âmenerrasûlü)</text>\n  <text x="45" y="217" font-size="10.5" fill="#166534">3) Şirk koşmayan müminlerin bağışlanacağı müjdesi</text>\n  <rect x="360" y="45" width="320" height="195" rx="10" fill="#faf5ff" stroke="#9333ea" stroke-width="2"/>\n  <text x="520" y="66" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#7e22ce">AKABE GÖRÜŞMELERİ VE BİATLARI</text>\n  <text x="375" y="92" font-size="11" font-weight="bold" fill="#6b21a8">• 620 — İlk Akabe Görüşmesi (6 Hazrecli):</text>\n  <text x="385" y="108" font-size="10.5" fill="#581c87">Medine\'ye (Yesrib) İslam\'ın ilk kıvılcımı taşındı.</text>\n  <text x="375" y="132" font-size="11" font-weight="bold" fill="#6b21a8">• 621 — Birinci Akabe Biatı (12 Medineli):</text>\n  <text x="385" y="148" font-size="10.5" fill="#581c87">Tevhid ve ahlak ilkeleri üzerine biat edildi;</text>\n  <text x="385" y="164" font-size="10.5" font-weight="bold" fill="#b91c1c">Mus\'ab b. Umeyr ilk öğretmen olarak gönderildi.</text>\n  <text x="375" y="188" font-size="11" font-weight="bold" fill="#6b21a8">• 622 — İkinci Akabe Biatı (73 Erkek, 2 Kadın):</text>\n  <text x="385" y="204" font-size="10.5" fill="#581c87">Hz. Peygamber\'i canları pahasına koruma sözü verildi</text>\n  <text x="385" y="220" font-size="10.5" fill="#581c87">ve Medine\'ye Hicret\'in hukuki zemini tamamlandı.</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">1. ÜNİTE ÖZETİ: MEKKE RİSALET DÖNEMİ KRONOLOJİSİ (610 - 622)</text>\n  <line x1="40" y1="130" x2="660" y2="130" stroke="#0284c7" stroke-width="4"/>\n  <circle cx="75" cy="130" r="8" fill="#0369a1"/>\n  <rect x="20" y="50" width="110" height="65" rx="8" fill="#e0f2fe" stroke="#0284c7" stroke-width="1.5"/>\n  <text x="75" y="68" text-anchor="middle" font-size="10.5" font-weight="bold" fill="#0c4a6e">610 - 613</text>\n  <text x="75" y="84" text-anchor="middle" font-size="9.5" fill="#075985">İlk Vahiy (Alak 1-5)</text>\n  <text x="75" y="98" text-anchor="middle" font-size="9.5" fill="#075985">Gizli Tebliğ Dönemi</text>\n  <text x="75" y="110" text-anchor="middle" font-size="9.5" font-weight="bold" fill="#0369a1">Dârü\'l-Erkam</text>\n  <circle cx="210" cy="130" r="8" fill="#0369a1"/>\n  <rect x="155" y="145" width="110" height="75" rx="8" fill="#e0f2fe" stroke="#0284c7" stroke-width="1.5"/>\n  <text x="210" y="163" text-anchor="middle" font-size="10.5" font-weight="bold" fill="#0c4a6e">613 - 615</text>\n  <text x="210" y="179" text-anchor="middle" font-size="9.5" fill="#075985">Açık Davet (Safa)</text>\n  <text x="210" y="193" text-anchor="middle" font-size="9.5" fill="#075985">Müşrik Baskıları</text>\n  <text x="210" y="207" text-anchor="middle" font-size="9.5" font-weight="bold" fill="#0369a1">Habeşistan Hicreti</text>\n  <circle cx="350" cy="130" r="8" fill="#d97706"/>\n  <rect x="290" y="50" width="120" height="65" rx="8" fill="#fef3c7" stroke="#d97706" stroke-width="1.5"/>\n  <text x="350" y="68" text-anchor="middle" font-size="10.5" font-weight="bold" fill="#78350f">616 - 619</text>\n  <text x="350" y="84" text-anchor="middle" font-size="9.5" fill="#92400e">Hz. Hamza &amp; Ömer</text>\n  <text x="350" y="98" text-anchor="middle" font-size="9.5" font-weight="bold" fill="#b45309">3 Yıllık Boykot</text>\n  <text x="350" y="110" text-anchor="middle" font-size="9.5" fill="#92400e">(Şi\'b-i Ebû Tâlib)</text>\n  <circle cx="490" cy="130" r="8" fill="#e11d48"/>\n  <rect x="430" y="145" width="120" height="75" rx="8" fill="#ffe4e6" stroke="#e11d48" stroke-width="1.5"/>\n  <text x="490" y="163" text-anchor="middle" font-size="10.5" font-weight="bold" fill="#881337">619 - 620</text>\n  <text x="490" y="179" text-anchor="middle" font-size="9.5" font-weight="bold" fill="#9f1239">Hüzün Yılı (619)</text>\n  <text x="490" y="193" text-anchor="middle" font-size="9.5" fill="#881337">Taif Yolculuğu (620)</text>\n  <text x="490" y="207" text-anchor="middle" font-size="9.5" fill="#9f1239">İsrâ ve Miraç Mucizesi</text>\n  <circle cx="625" cy="130" r="8" fill="#16a34a"/>\n  <rect x="565" y="50" width="115" height="65" rx="8" fill="#dcfce7" stroke="#16a34a" stroke-width="1.5"/>\n  <text x="622" y="68" text-anchor="middle" font-size="10.5" font-weight="bold" fill="#14532d">620 - 622</text>\n  <text x="622" y="84" text-anchor="middle" font-size="9.5" fill="#166534">1. ve 2. Akabe Biatı</text>\n  <text x="622" y="98" text-anchor="middle" font-size="9.5" fill="#166534">Mus\'ab b. Umeyr</text>\n  <text x="622" y="110" text-anchor="middle" font-size="9.5" font-weight="bold" fill="#15803d">Medine\'ye Hicret</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get("bolumler", [])):
        if i < len(SVGS):
            b["gorsel"] = SVGS[i]
